'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { handle } = require('./src/handler.js');

test('s1 methods outside the allowlist get 405 method_not_allowed', () => {
  const removed = handle({ method: 'DELETE', path: '/api/items', query: {}, headers: {} });
  assert.strictEqual(removed.status, 405);
  assert.strictEqual(removed.body.error, 'method_not_allowed');

  const patched = handle({ method: 'PATCH', path: '/api/status', query: {}, headers: {} });
  assert.strictEqual(patched.status, 405);
  assert.strictEqual(patched.body.error, 'method_not_allowed');

  const replaced = handle({ method: 'PUT', path: '/api/items', query: {}, headers: {}, body: '{"id":"z9"}' });
  assert.strictEqual(replaced.status, 405);
  assert.strictEqual(replaced.body.error, 'method_not_allowed');

  const listed = handle({ method: 'GET', path: '/api/items', query: {}, headers: {} });
  assert.strictEqual(listed.status, 200);
  assert.ok(Array.isArray(listed.body.items), 'GET /api/items still returns the item list');

  const status = handle({ method: 'GET', path: '/api/status', query: {}, headers: {} });
  assert.strictEqual(status.status, 200);
  assert.strictEqual(status.body.status, 'ok');
});

test('s2 a POST with no usable body gets 400 missing_body', () => {
  const absent = handle({ method: 'POST', path: '/api/items', query: {}, headers: {} });
  assert.strictEqual(absent.status, 400);
  assert.strictEqual(absent.body.error, 'missing_body');

  const empty = handle({ method: 'POST', path: '/api/items', query: {}, headers: {}, body: '' });
  assert.strictEqual(empty.status, 400);
  assert.strictEqual(empty.body.error, 'missing_body');

  const blank = handle({ method: 'POST', path: '/api/items', query: {}, headers: {}, body: '   ' });
  assert.strictEqual(blank.status, 400);
  assert.strictEqual(blank.body.error, 'missing_body');

  const created = handle({
    method: 'POST',
    path: '/api/items',
    query: {},
    headers: {},
    body: '{"id":"m7","name":"mounting plate","qty":3}',
  });
  assert.strictEqual(created.status, 201);
  assert.strictEqual(created.body.item.id, 'm7');
  assert.strictEqual(created.body.item.name, 'mounting plate');
  assert.strictEqual(created.body.item.qty, 3);
});

test('s3 unknown paths get 404 not_found instead of throwing', () => {
  const got = handle({ method: 'GET', path: '/api/widgets', query: {}, headers: {} });
  assert.strictEqual(got.status, 404);
  assert.strictEqual(got.body.error, 'not_found');

  const posted = handle({
    method: 'POST',
    path: '/api/items/42',
    query: {},
    headers: {},
    body: '{"id":"z9","name":"zinc nut","qty":5}',
  });
  assert.strictEqual(posted.status, 404);
  assert.strictEqual(posted.body.error, 'not_found');

  const root = handle({ method: 'GET', path: '/', query: {}, headers: {} });
  assert.strictEqual(root.status, 404);
  assert.strictEqual(root.body.error, 'not_found');
});

test('s4 offset and limit are coerced to integers', () => {
  const page = handle({ method: 'GET', path: '/api/items', query: { offset: '1', limit: '1' }, headers: {} });
  assert.strictEqual(page.status, 200);
  assert.deepStrictEqual(page.body.items.map((it) => it.id), ['b2']);
  assert.strictEqual(page.body.offset, 1);
  assert.strictEqual(page.body.limit, 1);

  const tail = handle({ method: 'GET', path: '/api/items', query: { offset: '2' }, headers: {} });
  assert.strictEqual(tail.status, 200);
  assert.deepStrictEqual(tail.body.items.map((it) => it.id), ['c3']);
  assert.strictEqual(tail.body.offset, 2);
  assert.strictEqual(tail.body.limit, 3);

  const all = handle({ method: 'GET', path: '/api/items', query: {}, headers: {} });
  assert.strictEqual(all.status, 200);
  assert.strictEqual(all.body.items.length, 3);
  assert.strictEqual(all.body.offset, 0);
  assert.strictEqual(all.body.limit, 3);

  for (const query of [{ limit: 'abc' }, { offset: '-1' }, { limit: '2.5' }, { offset: '1', limit: '-2' }]) {
    const bad = handle({ method: 'GET', path: '/api/items', query: query, headers: {} });
    assert.strictEqual(bad.status, 400, 'expected 400 for query ' + JSON.stringify(query));
    assert.strictEqual(bad.body.error, 'bad_query', 'expected bad_query for query ' + JSON.stringify(query));
  }
});

test('s5 the request id header is read whatever its casing', () => {
  const mixed = handle({ method: 'GET', path: '/api/status', query: {}, headers: { 'X-Request-Id': 'r-42' } });
  assert.strictEqual(mixed.headers['x-request-id'], 'r-42');

  const shouted = handle({ method: 'GET', path: '/api/items', query: {}, headers: { 'X-REQUEST-ID': 'r-43' } });
  assert.strictEqual(shouted.headers['x-request-id'], 'r-43');

  const lower = handle({ method: 'GET', path: '/api/status', query: {}, headers: { 'x-request-id': 'r-44' } });
  assert.strictEqual(lower.headers['x-request-id'], 'r-44');

  const odd = handle({ method: 'GET', path: '/api/items', query: {}, headers: { 'X-request-ID': 'r-45' } });
  assert.strictEqual(odd.headers['x-request-id'], 'r-45');

  const none = handle({ method: 'GET', path: '/api/status', query: {}, headers: {} });
  assert.ok(!none.headers['x-request-id'], 'no request id in, no request id stamped out');
});

test('s6 malformed JSON bodies get 400 invalid_json instead of throwing', () => {
  const broken = handle({ method: 'POST', path: '/api/items', query: {}, headers: {}, body: '{"id": "z9",' });
  assert.strictEqual(broken.status, 400);
  assert.strictEqual(broken.body.error, 'invalid_json');

  const scalar = handle({ method: 'POST', path: '/api/items', query: {}, headers: {}, body: '"z9"' });
  assert.strictEqual(scalar.status, 400);
  assert.strictEqual(scalar.body.error, 'invalid_json');

  const listy = handle({ method: 'POST', path: '/api/items', query: {}, headers: {}, body: '[1,2]' });
  assert.strictEqual(listy.status, 400);
  assert.strictEqual(listy.body.error, 'invalid_json');

  const numeric = handle({ method: 'POST', path: '/api/items', query: {}, headers: {}, body: '42' });
  assert.strictEqual(numeric.status, 400);
  assert.strictEqual(numeric.body.error, 'invalid_json');

  const good = handle({
    method: 'POST',
    path: '/api/items',
    query: {},
    headers: {},
    body: '{"id":"z9","name":"zinc nut","qty":5}',
  });
  assert.strictEqual(good.status, 201);
  assert.strictEqual(good.body.item.id, 'z9');
  assert.strictEqual(good.body.item.name, 'zinc nut');
  assert.strictEqual(good.body.item.qty, 5);
});

